<template>
 <div class="page-container calendar-page"><header><div><h1>业务日历管理</h1><p>维护自然日到交易日、工作日的映射，为 ETL_Date 提供明确的数据来源。</p></div><button class="btn btn-primary" :disabled="busy" @click="load">刷新</button></header>
 <p v-if="error" role="alert" class="calendar-error">{{ error }}</p><p v-if="notice" role="status">{{ notice }}</p>
 <nav class="calendar-tabs" role="tablist" aria-label="业务日历功能"><button v-for="(item,index) in tabs" :id="'calendar-tab-'+item.key" :key="item.key" type="button" role="tab" :aria-selected="activeTab===item.key" :aria-controls="'calendar-panel-'+item.key" :tabindex="activeTab===item.key?0:-1" :class="{active:activeTab===item.key}" @click="activeTab=item.key" @keydown="moveTab($event,index)">{{ item.label }}</button></nav>
 <section v-show="activeTab==='query'" id="calendar-panel-query" role="tabpanel" aria-labelledby="calendar-tab-query" class="card"><div class="calendar-toolbar"><label>日历类型<select v-model="kind" class="form-control" @change="page=1;load()"><option value="trading">交易日历</option><option value="working">工作日历</option></select></label><label>自然日起<input v-model="from" type="date" class="form-control" /></label><label>自然日止<input v-model="to" type="date" class="form-control" /></label><button class="btn btn-primary" :disabled="busy" @click="page=1;load()">查询</button><button v-if="store.user?.admin" class="btn btn-ghost" @click="edit()">新增记录</button></div>
 <p class="calendar-note">{{ table }} · ZRR 为自然日，{{ business }} 为对应业务日期；支持跨年映射。复合主键：ZRR + {{ business }}。</p><div class="table-wrap"><table class="table"><thead><tr><th v-for="c in columns" :key="c.key">{{ c.label }}<small>{{ c.key.toUpperCase() }}</small></th><th v-if="store.user?.admin">操作</th></tr></thead><tbody><tr v-for="r in rows" :key="r.zrr+':'+r[business.toLowerCase()]"><td v-for="c in columns" :key="c.key">{{ r[c.key] ?? '—' }}</td><td v-if="store.user?.admin"><button class="link-button" @click="edit(r)">编辑</button> <button class="link-button danger" @click="remove(r)">删除</button></td></tr><tr v-if="!rows.length"><td :colspan="columns.length+1">{{ busy ? '正在读取…' : '暂无日历记录，请导入 SQL 或新增记录' }}</td></tr></tbody></table></div><div class="calendar-pagination"><span>共 {{ total }} 条 · 第 {{ page }} 页</span><select v-model.number="size" aria-label="日历每页条数" @change="page=1;load()"><option :value="20">20 条</option><option :value="50">50 条</option><option :value="100">100 条</option></select><button class="btn btn-ghost" :disabled="busy || page<=1" @click="page--;load()">上一页</button><button class="btn btn-ghost" :disabled="busy || page*size>=total" @click="page++;load()">下一页</button></div></section>
 <section v-if="store.user?.admin" v-show="activeTab==='import'" id="calendar-panel-import" role="tabpanel" aria-labelledby="calendar-tab-import" class="card"><h2>上传 SQL 更新日历</h2><p class="calendar-note">支持两张日历表的 INSERT、按 ND=年度删除后插入，以及 CREATE TABLE。建表语句仅识别、不执行；同一文件可同时更新两张表。整个文件在同一事务中导入。</p><label>选择 .sql 文件<input type="file" accept=".sql" :disabled="importing" @change="readFile" /></label><p class="calendar-note">UTF-8 编码，最大 2 MB；不执行任意 SQL。禁止无条件删除、DROP、TRUNCATE 或其他表的语句。</p><p v-if="fileName">文件：{{ fileName }}</p><button class="btn btn-primary" :disabled="!sql || importing" @click="previewFile">预览更新</button>
 <div v-if="preview" class="calendar-preview"><h3>更新预览</h3><article v-for="(p,k) in preview.calendars" :key="k"><strong>{{ k==='trading'?'交易日历':'工作日历' }}</strong><p>删除年度：{{ p.delete_years.length ? p.delete_years.join('、') : '不删除' }} · 预计删除 {{ p.delete_count }} 条 · 写入 {{ p.row_count }} 条</p><p class="calendar-note">{{ p.mode }}</p><details><summary>查看前 {{ p.sample.length }} 条数据</summary><pre>{{ JSON.stringify(p.sample,null,2) }}</pre></details></article><p class="calendar-note">预计删除数量按预览时统计；提交时事务执行当前年度删除。其他年度保留。</p><label class="calendar-confirm"><input v-model="confirmed" type="checkbox" />我已核对日历类型、删除年度和写入数据</label><button class="btn btn-primary" :disabled="!confirmed || importing" @click="importFile">{{ importing ? '导入中…' : '确认导入更新' }}</button></div></section>
 <section v-show="activeTab==='mapping'" id="calendar-panel-mapping" role="tabpanel" aria-labelledby="calendar-tab-mapping" class="card"><h2>ETL_Date 映射查询</h2><div class="calendar-toolbar"><label>日历类型<select v-model="kind" class="form-control" @change="page=1;load()"><option value="trading">交易日历</option><option value="working">工作日历</option></select></label><label>自然日<input v-model="lookupDate" type="date" class="form-control" /></label><button class="btn btn-primary" @click="resolve">查询对应业务日期</button></div><p v-if="mapping">{{ mapping.status==='RESOLVED' ? 'ETL_Date：'+mapping.etl_date : mapping.status==='MISSING' ? '该自然日尚未配置映射' : mapping.status==='AMBIGUOUS' ? '该自然日存在多条映射，请核对：'+mapping.values.join('、') : '业务日不是有效日期，请修正数据' }}</p><p class="calendar-note">按 ZRR 精确查询；缺失和多义数据不自动推断。DolphinScheduler 实例的实际 ETL_Date 仍来自其业务参数。</p></section>
 <div v-if="form" class="modal-backdrop" @keydown.esc="form=null"><section class="modal-panel calendar-modal" role="dialog" aria-modal="true" aria-label="维护日历记录"><h2>{{ editing?'编辑日历记录':'新增日历记录' }}</h2><form @submit.prevent="save"><div class="calendar-form"><label v-for="c in columns" :key="c.key">{{ c.label }} ({{ c.key.toUpperCase() }})<input v-model="form[c.key]" class="form-control" type="number" step="1" :required="['zrr',business.toLowerCase()].includes(c.key)" :readonly="editing && ['zrr',business.toLowerCase()].includes(c.key)" /></label></div><p class="calendar-note">日期使用 YYYYMMDD；更改复合主键请先删除原记录再新增。</p><div class="calendar-toolbar"><button class="btn btn-ghost" type="button" @click="form=null">取消</button><button class="btn btn-primary" :disabled="busy">保存记录</button></div></form></section></div>
 </div>
</template>
<script setup>
import {ref,computed,nextTick,onMounted,onBeforeUnmount} from 'vue'
import {store} from '../store'
const activeTab=ref('query')
const tabs=computed(()=>[{key:'query',label:'日历查询维护'},...(store.user?.admin?[{key:'import',label:'SQL 导入更新'}]:[]),{key:'mapping',label:'ETL_Date 映射查询'}])
function moveTab(event,index){if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;event.preventDefault();const target=event.key==='Home'?0:event.key==='End'?tabs.value.length-1:(index+(event.key==='ArrowRight'?1:-1)+tabs.value.length)%tabs.value.length;activeTab.value=tabs.value[target].key;nextTick(()=>document.getElementById('calendar-tab-'+activeTab.value)?.focus())}
const kind=ref('trading'),rows=ref([]),total=ref(0),page=ref(1),size=ref(20),from=ref(''),to=ref(''),busy=ref(false),error=ref(''),notice=ref(''),form=ref(null),editing=ref(false)
const fileName=ref(''),sql=ref(''),preview=ref(null),confirmed=ref(false),importing=ref(false),lookupDate=ref(''),mapping=ref(null)
const business=computed(()=>kind.value==='trading'?'JYR':'GZR'),table=computed(()=>`t_ld_${kind.value}_calendar`)
const columns=computed(()=>[{key:'zrr',label:'自然日'},{key:business.value.toLowerCase(),label:kind.value==='trading'?'交易日':'工作日'},...['nd','jd','yf_xh','xq','ny','nz','xq_xh'].map((key,i)=>({key,label:['年度','季度','月份序号','星期','年月','年周','星期序号'][i]}))])
let generation=0,fileVersion=0,controller
async function request(path,method='GET',body){const r=await fetch('/api/calendars'+path,{method,credentials:'same-origin',headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.message || data.error || `请求失败 (${r.status})`);return data}
async function execute(fn){error.value='';try{await fn()}catch(e){error.value=e.message}}
async function load(){const current=++generation;controller?.abort();controller=new AbortController();busy.value=true;error.value='';mapping.value=null;try{const q=new URLSearchParams({page:page.value,page_size:size.value});if(from.value)q.set('from',from.value.replaceAll('-',''));if(to.value)q.set('to',to.value.replaceAll('-',''));const r=await fetch(`/api/calendars/${kind.value}?${q}`,{credentials:'same-origin',signal:controller.signal});const d=await r.json();if(!r.ok)throw Error(d.message||d.error||'日历查询失败');if(current!==generation)return;rows.value=d.items;total.value=d.total;page.value=d.page}catch(e){if(current===generation && e.name!=='AbortError'){rows.value=[];error.value=e.message}}finally{if(current===generation)busy.value=false}}
function edit(row){editing.value=!!row;form.value=Object.fromEntries(columns.value.map(c=>[c.key,row?.[c.key] ?? '']))}
async function save(){await execute(async()=>{busy.value=true;try{await request('/'+kind.value,'POST',Object.fromEntries(Object.entries(form.value).map(([k,v])=>[k,v===''?null:Number(v)])));form.value=null;notice.value='日历记录已保存';await load()}finally{busy.value=false}})}
async function remove(row){if(!confirm(`删除 ${row.zrr} → ${row[business.value.toLowerCase()]} 的${kind.value==='trading'?'交易日':'工作日'}映射？`))return;await execute(async()=>{await request(`/${kind.value}/${row.zrr}/${row[business.value.toLowerCase()]}`,'DELETE');notice.value='日历记录已删除';await load()})}
async function readFile(event){const version=++fileVersion;sql.value='';preview.value=null;confirmed.value=false;error.value='';const file=event.target.files?.[0];fileName.value=file?.name||'';if(!file)return;if(!/\.sql$/i.test(file.name)||file.size>2_000_000){error.value='请选择不超过 2 MB 的 .sql 文件';return}const text=await file.text();if(version!==fileVersion)return;if(text.includes('\uFFFD')){error.value='文件编码无效，请转为 UTF-8 后上传';return}sql.value=text}
async function previewFile(){await execute(async()=>{preview.value=null;confirmed.value=false;preview.value=await request('/import/preview','POST',{sql:sql.value})})}
async function importFile(){if(!confirmed.value||!preview.value)return;importing.value=true;await execute(async()=>{await request('/import/apply','POST',{sql:sql.value,preview_hash:preview.value.preview_hash});notice.value='日历数据已在同一事务内更新';preview.value=null;sql.value='';confirmed.value=false;await load()});importing.value=false}
async function resolve(){await execute(async()=>{if(!lookupDate.value)throw Error('请选择自然日');mapping.value=await request(`/${kind.value}/resolve?natural_date=${lookupDate.value.replaceAll('-','')}`)})}
onMounted(load);onBeforeUnmount(()=>{generation++;controller?.abort()})
</script>
<style scoped>
.calendar-tabs{display:flex;gap:6px;border-bottom:1px solid #dce7f4;margin-bottom:18px;overflow-x:auto;scrollbar-width:thin}.calendar-tabs button{flex-shrink:0;border:0;border-bottom:3px solid transparent;background:transparent;color:#64748b;padding:12px 18px;font-size:14px;cursor:pointer;white-space:nowrap}.calendar-tabs button.active{color:#087fbd;border-bottom-color:#078ccc;font-weight:600;background:#eef7ff}.calendar-tabs button:focus-visible{outline:2px solid #1689e7;outline-offset:-3px}.calendar-page header,.calendar-toolbar,.calendar-pagination{display:flex;align-items:center;gap:12px;flex-wrap:wrap}.calendar-page header{justify-content:space-between;margin-bottom:18px}.calendar-page h1{font-size:24px}.calendar-page h2{font-size:16px;margin-bottom:12px}.calendar-page header p,.calendar-note{font-size:12px;color:#687b89;line-height:1.8}.calendar-page .card{padding:18px;margin-bottom:16px}.calendar-toolbar label{display:flex;flex-direction:column;gap:6px;font-size:12px}.calendar-toolbar .btn{align-self:flex-end}.table th small{display:block;font-size:10px;color:#7d8fa2}.table td{white-space:nowrap;font-size:12px}.calendar-pagination{justify-content:flex-end;font-size:12px;padding-top:12px}.calendar-pagination span{margin-right:auto}.calendar-error{background:#fff1eb;color:#ad412f;padding:12px}.link-button{border:0;background:none;color:#147fba;cursor:pointer;font-size:12px}.link-button.danger{color:#b44235}.calendar-preview{margin-top:16px;padding:15px;background:#f5f9ff;border:1px solid #dce7f4;border-radius:5px}.calendar-preview h3{font-size:15px}.calendar-preview article{border-bottom:1px solid #dce7f4;padding:12px 0;font-size:12px}.calendar-preview pre{max-height:200px;overflow:auto}.calendar-confirm{display:flex;align-items:center;gap:8px;font-size:12px;margin:14px 0}.calendar-modal{max-width:700px;max-height:90vh;overflow:auto}.calendar-form{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px}.calendar-form label{font-size:12px;display:flex;flex-direction:column;gap:6px}@media(max-width:600px){.calendar-form{grid-template-columns:repeat(2,minmax(0,1fr))}.calendar-toolbar>*{max-width:100%}.calendar-page .card{padding:12px}}
</style>
